//! Durable, presentation-only summary generated by the auxiliary model.
use crate::i18n::Locale;
use crate::session::event::SessionEvent;
use crate::session::projection::{CheckpointRow, ProjectionUnit};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

pub(crate) const EVENT: &str = "clat/session-summary";
pub(crate) const PROJECTION: &str = "session_summary";
pub(crate) const MAX_SOURCE_MESSAGES: usize = 12;
/// Prompt-side budgets only（负责人裁定 2026-11-23）：请求文本告诉模型
/// "at most 80 characters / 40 words"，混排文本怎么理解由模型决定；
/// CLAT 不按这两个数验证、截断或拒绝——过控制字符清洗的原样入库展示。
pub(crate) const CHINESE_CHARACTER_LIMIT: usize = 80;
pub(crate) const ENGLISH_WORD_LIMIT: usize = 40;

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct ConversationSummary {
    pub text: String,
    pub locale: Locale,
    pub updated_at_ms: i64,
}

pub(super) fn validate(event: &SessionEvent, _: u32) -> Result<(), String> {
    parse(event)?;
    let sources = event.data["messageSeqs"]
        .as_array()
        .ok_or("missing summary source messages")?;
    if sources.is_empty() || sources.len() > MAX_SOURCE_MESSAGES {
        return Err("invalid summary source count".into());
    }
    let mut previous = None;
    for source in sources {
        let seq = source
            .as_u64()
            .filter(|seq| *seq < event.seq && Some(*seq) > previous)
            .ok_or("invalid summary source sequence")?;
        previous = Some(seq);
    }
    Ok(())
}

fn parse(event: &SessionEvent) -> Result<ConversationSummary, String> {
    let text = event.data["text"].as_str().ok_or("missing summary text")?;
    let locale = serde_json::from_value(event.data["locale"].clone())
        .map_err(|_| "invalid summary locale")?;
    let updated_at_ms = event.data["updatedAtMs"]
        .as_i64()
        .filter(|time| *time >= 0)
        .ok_or("invalid summary update time")?;
    Ok(ConversationSummary {
        text: text.to_owned(),
        locale,
        updated_at_ms,
    })
}

pub(crate) struct SummaryUnit {
    current: Option<ConversationSummary>,
    as_of: i64,
}

impl Default for SummaryUnit {
    fn default() -> Self {
        Self {
            current: None,
            as_of: -1,
        }
    }
}

impl ProjectionUnit for SummaryUnit {
    fn key(&self) -> &'static str {
        PROJECTION
    }

    fn state_version(&self) -> u64 {
        1
    }

    fn fold(&mut self, event: &SessionEvent) -> Result<(), String> {
        if event.event_type == EVENT {
            self.current = Some(parse(event)?);
        }
        self.as_of = event.seq as i64;
        Ok(())
    }

    fn snapshot(&self) -> Value {
        json!(self.current)
    }

    fn restore(&mut self, row: &CheckpointRow) -> Result<(), String> {
        let current: Option<ConversationSummary> =
            serde_json::from_value(row.val.clone()).map_err(|error| error.to_string())?;
        self.current = current;
        self.as_of = row.seq;
        Ok(())
    }

    fn as_of(&self) -> i64 {
        self.as_of
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::session::admission::admit_events;
    use crate::session::projection::{CheckpointIdentity, ProjectionRegistry};

    #[test]
    fn conversation_summary_is_admitted_log_only_and_restores_with_latest_text() {
        let summary = |seq, time_ms, text: &str| {
            SessionEvent::new(
                EVENT,
                seq,
                time_ms,
                json!({"text": text, "locale": "zh-Hans", "messageSeqs": [0], "updatedAtMs": time_ms}),
            )
            .log_only()
        };
        let legacy_text = "测".repeat(100);
        let initial = summary(1, 100, &legacy_text);
        assert!(admit_events(std::slice::from_ref(&initial)).is_ok());
        assert!(!super::super::is_surface_type(EVENT));
        assert_eq!(
            super::super::event_spec(EVENT).unwrap().replay,
            super::super::ReplayKind::Skip
        );

        // 负责人裁定（2026-11-23）：80/40 只是提示词约束，超限不再拒绝——
        // 中英混排长文本原样入库（重新加上长度检查会在这里翻红）。
        let oversized = summary(2, 150, &format!("{} renderMarkdown", "测".repeat(101)));
        assert!(admit_events(&[initial.clone(), oversized]).is_ok());

        let latest = summary(3, 200, "测试通过。");
        let mut future_source = latest.clone();
        future_source.data["messageSeqs"] = json!([3]);
        assert!(admit_events(&[future_source]).is_err());
        let mut live = ProjectionRegistry::clat();
        live.fold_one(&initial).unwrap();
        let identity = CheckpointIdentity::of(&crate::session::header::SessionHeader::new(
            crate::session::id::SessionId::new("summary"),
            None,
            0,
        ));
        let checkpoint = live.checkpoint(identity, 1);
        live.fold_one(&latest).unwrap();
        let mut restored = ProjectionRegistry::clat();
        restored.restore(&checkpoint, &[], 2).unwrap();
        assert_eq!(
            restored.state_snapshot(PROJECTION).unwrap()["text"],
            legacy_text,
        );
        restored.restore(&checkpoint, &[latest], 2).unwrap();
        assert_eq!(
            restored.state_snapshot(PROJECTION),
            live.state_snapshot(PROJECTION)
        );
        assert_eq!(
            live.state_snapshot(PROJECTION).unwrap(),
            json!({
                "text":"测试通过。","locale":"zh-Hans","updated_at_ms":200,
            })
        );
    }
}
